package com.spanova.trafficloads; import java.util.*; public final class SeismicSpectrumService { public SeismicSpectrumResult resolve(SeismicSpectrumRequest r){if(r==null||r.agR()==null||r.agR()<=0||r.importanceFactor()==null||r.importanceFactor()<=0)return new SeismicSpectrumResult("INVALID",0,0,0,0,0,0,List.of()); double[][] v=r.spectrumType()!=null&&r.spectrumType().equals("Type 2")?new double[][]{{1,.05,.25,1.2},{1.35,.05,.25,1.2},{1.5,.1,.25,1.2},{1.8,.1,.3,1.2},{1.6,.05,.25,1.2}}:new double[][]{{1,.15,.4,2},{1.2,.15,.5,2},{1.15,.2,.6,2},{1.35,.2,.8,2},{1.4,.15,.5,2}};int i=r.groundType()==null?-1:"ABCDE".indexOf(r.groundType());if(i<0)return new SeismicSpectrumResult("INVALID",0,0,0,0,0,0,List.of());double ag=r.agR()*r.importanceFactor(),s=v[i][0],tb=v[i][1],tc=v[i][2],td=v[i][3];var p=new ArrayList<SeismicSpectrumResult.Point>();for(int n=0;n<=400;n++){double t=n*.01,se=ag*s*(t<=tb?1+t/tb*1.5:t<=tc?2.5:t<=td?2.5*tc/t:2.5*tc*td/(t*t));p.add(new SeismicSpectrumResult.Point(t,se));}return new SeismicSpectrumResult("VALID",ag,s,tb,tc,td,ag*s*2.5,p);}}
